query AllCompetitionsFilter($urn: [URN!]!) {
  Cards(cardsURN: $urn) {
    ...FilteredCouponCardGroupAllCompetitionsFilterOptions
    __typename
  }
}

fragment FilteredCouponCardGroupAllCompetitionsFilterOptions on FilteredCouponCardGroup {
  filterOptions {
    __typename
    competitionsFilter {
      urn
      allCompetitions {
        competitions {
          __typename
          urn
          name
          competitionId
          sport {
            __typename
            urn
            name
            sportId
          }
        }
        country {
          urn
          code
          flag {
            vector
            small
            medium
            large
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
  }
  __typename
}

